// WellRoost Vibe Marketing Intent Scoring & Persona Classification
const item = $input.first().json.body || $input.first().json;

const assetSlug = item.asset_slug || item.assetId || 'unknown-asset';
const eventType = item.event_type || item.eventType || 'view';
const category = item.category || 'General';
const title = item.title || 'WellRoost Decision Engine';
const metadata = item.metadata || {};
const domain = item.domain || 'wellroost.com';

// 1. Calculate Intent Score
let intentScore = 10;
switch (eventType) {
  case 'view':
    intentScore = 10;
    break;
  case 'engage':
    intentScore = 35;
    break;
  case 'input_change':
    intentScore = 60;
    break;
  case 'complete':
    intentScore = 85;
    break;
  case 'lead_convert':
    intentScore = 100;
    break;
  default:
    intentScore = 20;
}

// Bonus score if user spends meaningful session time or tests complex inputs
if (metadata.metricsPreview) {
  intentScore += 10;
}

// 2. Persona Classification based on WellRoost Directives (skill.md)
let persona = 'General Homeowner';
let suggestedAction = 'Monitor general activity';

if (category.includes('EQUITY') || assetSlug.includes('arv') || assetSlug.includes('remodeling-roi')) {
  persona = 'The High-Stakes Renovator';
  suggestedAction = 'Evaluate comp ARV uplift and contractor over-improvement risk';
} else if (category.includes('MOVE') || assetSlug.includes('relocation') || assetSlug.includes('move-or-improve')) {
  persona = 'The Move vs. Improve Evaluator';
  suggestedAction = 'Model 5-year friction delta and transaction carry costs';
} else if (category.includes('ENERGY') || assetSlug.includes('heat-pump') || assetSlug.includes('rebate')) {
  persona = 'The Energy & Systems Optimizer';
  suggestedAction = 'Verify Section 25C & state HOMES/HEAR rebate qualification';
} else if (category.includes('CAPEX') || assetSlug.includes('underwrite') || assetSlug.includes('remodelytics')) {
  persona = 'The Real Estate & Equity Investor';
  suggestedAction = 'Underwrite 70% rule MAO and combined LTV (CLTV) thresholds';
}

// 3. Smart Brevity Notification Payload
const alertSummary = `*High-Intent Decision Engine Activity on ${domain}*\n` +
  `• *Asset*: ${title} (${category})\n` +
  `• *Persona*: ${persona}\n` +
  `• *Intent Score*: ${intentScore}/100 [Event: ${eventType.toUpperCase()}]\n` +
  `• *Strategic Focus*: ${suggestedAction}\n` +
  `• *Path*: ${metadata.pathname || '/calculators/'}`;

return [{
  json: {
    asset_id: item.asset_id || assetSlug,
    asset_slug: assetSlug,
    event_type: eventType,
    category,
    title,
    domain,
    metadata,
    intentScore,
    isHighIntent: intentScore >= 70,
    persona,
    suggestedAction,
    alertSummary,
    processed_at: new Date().toISOString()
  }
}];
